def norm(lang): return lang if lang in LANGS else "en"
def offer_name(lang, offer): return (KB_I18N.get(lang, {}).get(offer["id"]) or (offer["name"],))[0]
def nums(s): return {n.replace(",", "") for n in re.findall(r"\d[\d,]*", s)}

def notice_for(lang, english):
    if lang == "en": return english
    n = dict(NOTICE[lang]); n["version"] = english["version"]; n["grievance_contact"] = english["grievance_contact"]
    return n

def localized_script(match, lang, kb):
    """Assemble the script from fixed, translated fact templates. Numbers/URLs are tested to equal the English facts."""
    by_id = {d["id"]: d for d in kb}
    ids = [o["id"] for o in match["offers"]]
    parts, missing = [OPENER[lang]], []
    for i in ids:
        tr = KB_I18N.get(lang, {}).get(i)
        parts.append(tr[1] if tr else by_id[i]["text"])
        if not tr: missing.append(i)
    script = " ".join(parts)
    allowed = set().union(*[nums(by_id[i]["text"]) for i in ids]) | {"90"} if ids else {"90"}
    grounded = nums(script) <= allowed
    from indic import readability_indic
    read = readability_indic(script, lang)
    reviewed = REVIEW.get(lang) is not None
    verified = all(by_id[i]["verified"] for i in ids)
    return {"script": script, "grade": None, "reading_ease": None, "readability": read, "grounded": grounded,
            "meaning_ok": not missing, "facts_used": ids, "translation_reviewed": reviewed,
            "safe_to_ship": grounded and not missing and reviewed and verified}
